import numpy as np
from functools import cmp_to_key

PARAMETER_TOL = 1e-6
RESPONSE_TOL = 1e-8
BOUND_TOL = 1e-9


def _predict_calibration_responses(root):
    root = np.asarray(
        root,
        dtype=float,
    )

    offsets_deg = root[:-1]
    rho_c0 = float(root[-1])

    n_cells = ideal_conductivity_tensors.shape[0]

    angles_rad = np.deg2rad(
        offsets_deg
    )

    cos_delta = np.cos(
        angles_rad
    )

    sin_delta = np.sin(
        angles_rad
    )

    offset_rotations = np.empty(
        (n_cells, 2, 2),
        dtype=float,
    )

    offset_rotations[:, 0, 0] = cos_delta
    offset_rotations[:, 0, 1] = -sin_delta
    offset_rotations[:, 1, 0] = sin_delta
    offset_rotations[:, 1, 1] = cos_delta

    realized_tensors = (
        offset_rotations
        @ ideal_conductivity_tensors
        @ np.swapaxes(
            offset_rotations,
            1,
            2,
        )
    )

    heat_capacities = (
        rho_c0
        / determinants
    )

    t_xx = calibration_hessians[:, :, 0]
    t_xy = calibration_hessians[:, :, 1]
    t_yy = calibration_hessians[:, :, 2]

    contractions = (
        realized_tensors[
            None,
            :,
            0,
            0,
        ]
        * t_xx
        + 2.0
        * realized_tensors[
            None,
            :,
            0,
            1,
        ]
        * t_xy
        + realized_tensors[
            None,
            :,
            1,
            1,
        ]
        * t_yy
    )

    temperature_rates = (
        contractions
        / heat_capacities[
            None,
            :,
        ]
    )

    return (
        temperature_rates
        @ weights
    )


